import { Component, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { PagoCargaMasiva } from '../../../models/pago.carga.masiva';
import { CurrencyPipe, DatePipe, NgClass } from '@angular/common';
import { PagoCargaMasivaService } from '../../../controllers/pago.carga.masiva.service';
import { FormsModule } from '@angular/forms';
import { CreditoAbonoService } from '../../../controllers/credito.abono.service';
import { CreditoService } from '../../../controllers/credito.service';
import { BuscadorCreditosComponent } from "../../../main/estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Credito } from '../../../models/credito.model';
import { UtilsService } from '../../../services/utils.service';
import { FileInputComponent } from "../../../shared/file-input/file-input.component";

@Component({
    selector: 'app-editar-carga-masiva',
    imports: [
    FormsModule,
    BuscadorCreditosComponent,
    DatePipe,
    CurrencyPipe,
    NgClass,
    FileInputComponent
],
    templateUrl: './editar-carga-masiva.component.html',
    styleUrl: './editar-carga-masiva.component.css'
})
export class EditarCargaMasivaComponent {
  @ViewChild('fileInput') fileInput?: FileInputComponent
  @Input() cargaMasivaEdit?: PagoCargaMasiva
  @Output() cargaMasivaEditChange= new EventEmitter<PagoCargaMasiva>()
  isAccordionOpen=true
  credito_id:number=0
  credito?:Credito
  nota=''

  constructor(
    private creditoController: CreditoService,
    private abonoController: CreditoAbonoService,
    public pagoMasivoController: PagoCargaMasivaService,
    public utilsService: UtilsService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['cargaMasivaEdit'] && this.cargaMasivaEdit) {
      const creditoId= this.cargaMasivaEdit.credito_id ?? this.cargaMasivaEdit.creditos_abonos?.credito_id
      this.credito_id=0
      this.credito=undefined
      if(creditoId){
        this.credito_id= creditoId
        this.setCredito()
      }
    }
  }

  public async setCredito(){
    this.credito= await this.creditoController.find(this.credito_id, ['*'])
  }

  sePagoDeMas(){
    return (this.credito?.estado_cuenta?.monto_total_pagado??0) > (this.credito?.estado_cuenta?.monto_total_mas_intereses??0) && this.cargaMasivaEdit?.nota!=='MIGRADO'
  }

  async asociar(){
    if(!this.cargaMasivaEdit) return;
    this.cargaMasivaEdit!.credito_id=this.credito_id!
    if(this.cargaMasivaEdit?.creditos_abonos){
      const res = await this.abonoController.switch(this.cargaMasivaEdit.creditos_abonos, {nota:this.nota})
      if(!res){
        return;
      }
      this.cargaMasivaEdit.creditos_abonos=undefined
    }
    this.cargaMasivaEdit.nota= this.nota
    const res = await this.pagoMasivoController.asociarCargaMasiva(this.cargaMasivaEdit!)
    if(res){
      if(this.cargaMasivaEdit?.credito_id){ 
        //actualizar estado cuenta
        await this.creditoController.actualizarEstadoCuenta(this.cargaMasivaEdit?.credito_id)
        const cargaupdate = await this.pagoMasivoController.find(this.cargaMasivaEdit.id, ['creditosAbonos.usuarios', 'usuarios'])
        this.cargaMasivaEdit.creditos_abonos = cargaupdate?.creditos_abonos
        this.cargaMasivaEdit.usuarios = cargaupdate?.usuarios
      }
      this.cargaMasivaEditChange.emit(this.cargaMasivaEdit)
    }
  }
}
